  where line <> ''
)
insert into public.psgc_locations (code, label, kind, parent_code)
select s.code, s.label, s.kind, case s.kind
  when 'R' then null
  when 'B' then left(s.code, 7) || '000'
  when 'D' then left(s.code, 5) || '00000'
  when 'L' then coalesce(province.code, left(s.code, 2) || '00000000')
  else left(s.code, 2) || '00000000'
end
from source as s
left join source as province on province.code = left(s.code, 5) || '00000' and province.kind = 'P';
